    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    for (int i = end - 1; i >= 0; i--) {
        char currentChar = headerPart.charAt(i);
        char nextChar = (i + 1 < headerPart.length()) ? headerPart.charAt(i + 1) : '\0';

        if (currentChar == '\n' && nextChar == '\r') {
            return i + 1;
        }
    }

    throw new IllegalArgumentException("End of line marker \r\n not found");
}

