public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

    Class<?>[] resolvedClasses = new Class<?>[actualTypeArguments.length];

    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type actualTypeArgument = actualTypeArguments[i];
        if (actualTypeArgument instanceof Class) {
            resolvedClasses[i] = (Class<?>) actualTypeArgument;
        } else if (actualTypeArgument instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArgument;
            Type resolvedType = resolveTypeVariable(typeVariable, targetType);
            if (resolvedType instanceof Class) {
                resolvedClasses[i] = (Class<?>) resolvedType;
            } else {
                return null; // Unable to resolve type variable
            }
        } else {
            return null; // Unsupported type argument
        }
    }

    return resolvedClasses;
}

private static Type resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    AnnotatedType[] annotations = targetType.getAnnotatedInterfaces();
    for (AnnotatedType annotation : annotations) {
        ParameterizedType parameterizedType = (ParameterizedType) annotation.getType();
        if (parameterizedType.getRawType().equals(typeVariable.getGenericDeclaration())) {
            return parameterizedType.getActualTypeArguments()[0];
        }
    }
    return null; // Unable to resolve type variable
}

