static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Adjust the day based on the dayStep
    int adjustedDay = day - day % dayStep;
    if (adjustedDay < 1) {
        month--;
        if (month < 1) {
            year--;
            month = 12;
        }
        adjustedDay += 31; // Assuming the worst-case scenario of 31 days in the month
    }

    // Adjust the month and year if needed
    if (day > 31) {
        month++;
        if (month > 12) {
            year++;
            month = 1;
        }
    }

    // Handle overflow for days in February
    if (month == 2 && day > 29) {
        day = 29; // Assuming a leap year for simplicity
    }

    // Format the new time bucket
    return year * 10000L + month * 100L + adjustedDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("The provided CharSequence cannot be null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("Index and length must be non-negative");
    }
    if (index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }

    int size = 0;
    int endIndex = index + len;
    for (int i = index; i < endIndex; i++) {
        int charCode = str.charAt(i);
        if (charCode <= 0x7F) {
            size += 1;
        } else if (charCode <= 0x7FF) {
            size += 2;
        } else if (charCode <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

