private static String substProperties(String str, Properties props) {
    int idx = -1;
    while ((idx = str.indexOf("${", idx + 2)) != -1) {
        int end = str.indexOf('}', idx);
        if (end == -1) {
            break;
        }

        String varName = str.substring(idx + 2, end);
        String varValue = props.getProperty(varName.trim());
        if (varValue != null) {
            str = str.substring(0, idx) + varValue + str.substring(end + 1);
            idx = idx + varValue.length() - 1;
        } else {
            break;
        }
    }

    return str;
}

