        if (constantPool.get(i) instanceof CONSTANT_NameAndType_info) {
            CONSTANT_NameAndType_info info = (CONSTANT_NameAndType_info) constantPool.get(i);
            if (info.getName().equals(name) && info.getDescriptor().equals(descriptor)) {
                return i; // Return the existing index
            }
        }
    }

    // Create a new CONSTANT_NameAndType_info
    CONSTANT_NameAndType_info newInfo = new CONSTANT_NameAndType_info(name, descriptor);
