    // Step 5: Iterate through the segments to find ranges
    for (int i = 1; i < currentSegments.size(); i++) {
        ProfileSegment currentSegment = currentSegments.get(i);
        ProfileSegment previousSegment = currentSegments.get(i - 1);

        // Step 6: Check if the current segment overlaps with the previous one
        if (currentSegment.getStartTime() <= previousSegment.getEndTime()) {
            // If it overlaps, update the end of the current range
            start = Math.min(start, currentSegment.getStartTime());
        } else {
            // If it doesn't overlap, add the current range to the list and start a new one
            sequenceRanges.add(new SequenceRange(start, previousSegment.getEndTime()));
            start = currentSegment.getStartTime();
        }
    }

    // Step 7: Add the last sequence range to the list
    sequenceRanges.add(new SequenceRange(start, currentSegments.get(currentSegments.size() - 1).getEndTime()));

    // Step 8: Return the list of sequence ranges
    return sequenceRanges;
}

