private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<Integer,E> graph){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.getEdges()) {
        int u = edge.getSource().getId();
        int v = edge.getTarget().getId();

        List<Pair<Integer,Integer>> localSeparatorList = computeLocalSeparatorList(graph, u, v);

        globalSeparatorList.add(Pair.with(localSeparatorList, edge));
    }

    return globalSeparatorList;
}

private List<Pair<Integer,Integer>> computeLocalSeparatorList(Graph<Integer,E> graph, int u, int v) {
    Set<Integer> uNeighborhood = new HashSet<>(graph.getNeighbors(u));
    Set<Integer> vNeighborhood = new HashSet<>(graph.getNeighbors(v));

    uNeighborhood.remove(v);
    vNeighborhood.remove(u);

    List<Pair<Integer,Integer>> separatorList = new ArrayList<>();

    for (int neighbor : uNeighborhood) {
        if (!vNeighborhood.contains(neighbor)) {
            continue;
        }

        Set<Integer> intersection = new HashSet<>(uNeighborhood);
        intersection.retainAll(vNeighborhood);
        intersection.remove(neighbor);

        if (intersection.isEmpty()) {
            continue;
        }

        List<Pair<Integer,Integer>> segment = new ArrayList<>();

        for (int segNode : intersection) {
            if (isSeparator(graph, u, v, neighbor, segNode)) {
                segment.add(Pair.with(neighbor, segNode));
            }
        }

        separatorList.add(Pair.with(segment, neighbor));
    }

    return separatorList;
}

private boolean isSeparator(Graph<Integer,E> graph, int u, int v, int w, int segNode) {
    Set<Integer> uPath = new HashSet<>();
    Set<Integer> vPath = new HashSet<>();

    uPath.addAll(graph.getPath(u, segNode));
    vPath.addAll(graph.getPath(v, segNode));

    uPath.remove(u);
    uPath.remove(segNode);

    vPath.remove(v);
    vPath.remove(segNode);

    uPath.retainAll(vPath);

    return uPath.isEmpty();
}

