private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true; // An empty subgraph is trivially a clique
    }

    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (vertex.equals(otherVertex)) {
                continue; // No need to check a vertex with itself
            }
            if (!graph.containsEdge(vertex, otherVertex)) {
                return false; // Missing edge, not a clique
            }
        }
    }

    return true; // All vertices are connected, it's a clique
}

