public int readTag() throws IOException {
    int firstByte = input.read();
    if (firstByte == -1) {
        return 0; // EOF
    }
    int tag = firstByte << 3;
    int wireType = firstByte & 0x07;
    if (wireType == 0) {
        // Varint for field number
        int b;
        while ((b = input.read()) < 0) {
            tag |= (b & 0x7F) << 7;
        }
        tag |= (b & 0x7F) << 7;
    } else if (wireType == 1) {
        // 64-bit integer (int64, fixed64, uint64, sint64, fixed32, sfixed32, uint32)
        // Skip the 64-bit value
        for (int i = 0; i < 8; i++) {
            input.read();
        }
    } else if (wireType == 2) {
        // Length-delimited field (string, bytes, embedded messages, packed repeated fields)
        int size = readVarint();
        // Skip the size of the field
        for (int i = 0; i < size; i++) {
            input.read();
        }
    } else if (wireType == 5) {
        // 32-bit integer (int32, fixed32, uint32, sint32, sfixed32)
        // Skip the 32-bit value
        input.read();
        input.read();
        input.read();
        input.read();
    } else {
        throw new IOException("Invalid wire type: " + wireType);
    }
    return tag;
}

private int readVarint() throws IOException {
    int result = 0;
    for (int shift = 0; shift < 32; shift += 7) {
        int b = input.read();
        if (b == -1) {
            throw new IOException("Unexpected EOF while decoding varint");
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
    }
    throw new IOException("Out of range varint encountered");
}

