public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    if (file == null || file.isDirectory() || !file.exists()) {
        throw new IllegalArgumentException("Invalid file path");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid time ranges");
    }

    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            // Assuming each line contains thread snapshot data
            ThreadSnapshot snapshot = ThreadSnapshot.parseFromLine(line);
            if (snapshot != null && containsInRange(snapshot.getTimestamp(), timeRanges)) {
                snapshots.add(snapshot);
            }
        }
    }

    return snapshots;
}

private static boolean containsInRange(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
            return true;
        }
    }
    return false;
}
